package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PhoneNumberVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property phone number of user profile ")
  void test_phone_number_v_o_builder() {
    Assertions.assertFalse(PhoneNumberVO.nullValue().getPhoneNumber().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(PhoneNumberVO.tryFrom(null).getPhoneNumber().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", PhoneNumberVO.from("one").getPhoneNumber().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> PhoneNumberVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", PhoneNumberVO.from("one").toString());
  }
}
